def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    strings = data[1:]

    max_beauty = 0
    current_char = None
    current_length = 0

    for i in range(n):
        s = strings[i]
        if i == 0:
            max_beauty = max(max_beauty, len(s))
            current_char = s[-1]
            current_length = 1
        else:
            for j in range(len(s)):
                if s[j] == current_char:
                    current_length += 1
                    max_beauty = max(max_beauty, current_length)
                else:
                    current_char = s[j]
                    current_length = 1

    print(max_beauty)

if __name__ == "__main__":
    main()
